import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Architecture — Designing for Change","description":"From single-file services to distributed systems — modularity, failure domains and evolution as first-class concerns.","frontmatter":{"title":"Architecture — Designing for Change","description":"From single-file services to distributed systems — modularity, failure domains and evolution as first-class concerns."},"headers":[],"relativePath":"en/skills/architecture/index.md","filePath":"en/skills/architecture/index.md"}`),a={name:`en/skills/architecture/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="architecture-—-designing-for-change" tabindex="-1">Architecture — Designing for Change <a class="header-anchor" href="#architecture-—-designing-for-change" aria-label="Permalink to “Architecture — Designing for Change”">​</a></h1><p>Architecture is the set of decisions that are expensive to change later. My bias: start as small as possible — sometimes a <a href="/Usf/en/projects/glm-free-api/">single file</a> — but with seams in the right places, so growth means replacing modules instead of rewriting systems.</p><h2 id="principles-i-design-by" tabindex="-1">Principles I design by <a class="header-anchor" href="#principles-i-design-by" aria-label="Permalink to “Principles I design by”">​</a></h2><ul><li><strong>Failure domains.</strong> Anything that can die should die alone — routers isolate providers, panels isolate users.</li><li><strong>Boring technology first.</strong> Innovation budget spent on the one thing that is actually new.</li><li><strong>Interfaces over implementations.</strong> The OpenAI API shape became a standard precisely because contracts outlive products.</li><li><strong>State is the hard part.</strong> Keep it small, keep it explicit, back it up, and know where every byte lives.</li><li><strong>Evolution paths.</strong> Every design gets a &quot;when this outgrows itself&quot; note — written while the trade-offs are fresh.</li></ul><p>The portfolio of projects itself follows this arc: bridges (<a href="/Usf/en/projects/glm-free-api/">one file</a>) grew into routers (<a href="/Usf/en/projects/omnirouter/">OmniRouter</a>), routers grew into stacks (<a href="/Usf/en/projects/hermes-stack/">Hermes</a>) — each step replacing a module, not rewriting a system. That, to me, is what &quot;versatile engineer&quot; actually means: not knowing everything, but building so that you can learn anything next.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};